return $build(array(
 'key'=>'indonesia-sd5-fase-c','grade'=>'sd_5','category'=>'bahasa-indonesia','slug'=>'bahasa-indonesia-kelas-5-analisis-teks-argumen-dan-karya',
 'title'=>'Bahasa Indonesia Kelas 5 — Analisis Teks, Argumen, dan Karya',
 'summary'=>'Delapan bab awal Fase C: makna lugas/kias, gagasan dan bukti, menyimak, analisis cerita, teks penjelasan, pendapat beralasan, surat/puisi original dan laporan/revisi. Tugas terbuka melatih kalimat lebih kompleks serta presentasi; kuis bukan ukuran tunggal keterampilan bahasa.',
 'objectives'=>"Menganalisis informasi dan membedakan fakta teks dari dugaan.\nMenggunakan kosakata lugas/kias sesuai konteks.\nMenjelaskan hubungan sebab-akibat dan pendapat beralasan.\nMenyusun karya serta laporan dengan kalimat saling terkait.",
